// Loads the repo's env files before anything reads process.env. Imported first by main.ts.
// Not node --env-file: under --watch, Node watches those files, and on macOS that watch fires for
// any change in their folder (the repo root), so every file written there restarted the dev API.
// Existing variables win, so the real environment (production) overrides both files, and
// .env.local (personal keys) overrides .env (generated by npm run env).
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

for (const name of ['.env.local', '.env']) {
  const path = fileURLToPath(new URL(`../../../${name}`, import.meta.url));
  if (existsSync(path)) process.loadEnvFile(path);
}
